<script>
document.addEventListener('DOMContentLoaded', () => {
    const modal = document.getElementById('claim-detail-preview-modal');
    const frame = modal?.querySelector('[data-claim-detail-preview-frame]');
    const fields = modal?.querySelector('[data-claim-detail-preview-fields]');
    if (!modal || !frame || !fields || !window.bootstrap?.Modal) return;
    document.addEventListener('click', (event) => {
        const trigger = event.target.closest('[data-claim-detail-preview]');
        if (!trigger) return;
        const detail = [['Tanggal nota', trigger.dataset.receiptDate], ['Tanggal kegiatan', trigger.dataset.activityDate], ['Kategori biaya', trigger.dataset.category], ['Nominal', `${trigger.dataset.currency} ${trigger.dataset.amount}`], ['Referensi nota', trigger.dataset.reference], ['Deskripsi', trigger.dataset.description], ['Nama file', trigger.dataset.filename]];
        fields.replaceChildren(...detail.flatMap(([label, value]) => { const term = document.createElement('dt'); term.className = 'claim-verification-label'; term.textContent = label; const description = document.createElement('dd'); description.className = 'claim-verification-value'; description.textContent = value || '—'; return [term, description]; }));
        frame.src = trigger.dataset.claimDetailPreview;
        window.bootstrap.Modal.getOrCreateInstance(modal).show();
    });
    modal.addEventListener('hidden.bs.modal', () => { frame.src = 'about:blank'; });
});
</script>
